//! Shared media fixture helpers for `video` and `native_surface` unit tests;
//! executable `@Test` suites live in `Tests/RuneTests/video/video_tests.swift`.

#if !os(WASI)
import Foundation

enum VideoTestFixtures {
    /// Four 0.25s frames (`64x36`): Red, Green, Blue, White (`rgbw.mp4`).
    static let rgbwMP4Base64 =
        ""

    /// Rotated quadrant clip (`quadrants-rot90.mp4`).
    static let quadrantsRot90MP4Base64 =
        ""

    /// ~1.0s AAC silence (`silence.m4a`).
    static let silenceM4ABase64 =
        ""

    static func writeFixture(name: String, base64: String) -> String {
        let dir = FileManager.default.temporaryDirectory.appendingPathComponent("rune-test-fixtures", isDirectory: true)
        try? FileManager.default.createDirectory(at: dir, withIntermediateDirectories: true)
        let url = dir.appendingPathComponent(name)
        if !FileManager.default.fileExists(atPath: url.path),
           let data = Data(base64Encoded: base64) {
            try? data.write(to: url, options: .atomic)
        }
        return url.path
    }

    static func writeSilenceWav() -> String {
        let dir = FileManager.default.temporaryDirectory.appendingPathComponent("rune-test-fixtures", isDirectory: true)
        try? FileManager.default.createDirectory(at: dir, withIntermediateDirectories: true)
        let url = dir.appendingPathComponent("silence.wav")
        if !FileManager.default.fileExists(atPath: url.path) {
            let sampleCount: UInt64 = 24_000 // 0.5 s at 48 kHz mono
            if case .success(let hdr) = foreignWavHeader(rate: 48_000, channels: 1, samples: sampleCount) {
                var bytes = hdr
                bytes.append(contentsOf: [UInt8](repeating: 0, count: Int(sampleCount) * 2))
                try? Data(bytes).write(to: url, options: .atomic)
            }
        }
        return url.path
    }
}
#endif
